create temporary table companion_preservation(table_name text primary key,digest text) on commit drop;
do $$declare t text;d text;begin for t in select tablename from pg_tables where schemaname='public' loop execute format('select md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text)::text,''[]'')) from public.%I x',t) into d;insert into companion_preservation values(t,d);end loop;end $$;
create table public.project_companion_items(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,
 tool text not null,label text not null check(length(trim(label)) between 1 and 200),status text not null,
 details jsonb not null default '{}' check(jsonb_typeof(details)='object' and octet_length(details::text)<=24000),
 source_key text check(length(source_key)<=200),revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,tool,source_key));
create index project_companion_items_scope_idx on public.project_companion_items(project_id,tool,created_at,id);
alter table public.project_companion_items enable row level security;
revoke all on public.project_companion_items from public,anon,authenticated;grant select,insert,update,delete on public.project_companion_items to authenticated;
create policy "Companion read" on public.project_companion_items for select to authenticated using(public.can_access_project_operations(project_id) and (tool not in ('urgent_expenses','extras') or public.is_admin()));
create policy "Companion add" on public.project_companion_items for insert to authenticated with check(public.can_manage_project_operations(project_id) and (tool not in ('urgent_expenses','extras') or public.is_admin()));
create policy "Companion edit" on public.project_companion_items for update to authenticated using(public.can_manage_project_operations(project_id) and (tool not in ('urgent_expenses','extras') or public.is_admin())) with check(public.can_manage_project_operations(project_id) and (tool not in ('urgent_expenses','extras') or public.is_admin()));
create policy "Companion remove" on public.project_companion_items for delete to authenticated using(public.can_manage_project_operations(project_id) and (tool not in ('urgent_expenses','extras') or public.is_admin()));
