create function public.validate_equipment_setting_preset() returns trigger language plpgsql security invoker set search_path='' as $$
declare c jsonb;k text;ids uuid[]:='{}';cid uuid;lo numeric;hi numeric;v numeric;s numeric;begin
 if tg_op='UPDATE' and new.revision=old.revision and (to_jsonb(new)-array['equipment_id','photo_document_id'])=(to_jsonb(old)-array['equipment_id','photo_document_id']) and ((old.equipment_id is not null and new.equipment_id is null) or (old.photo_document_id is not null and new.photo_document_id is null)) then new.revision:=old.revision+1;end if;
 if tg_op='UPDATE' then if new.project_id<>old.project_id or new.revision<>old.revision+1 then raise exception 'La fiche a changé : rechargez-la' using errcode='23514';end if;new.created_at:=old.created_at;elsif new.revision<>1 then raise exception 'Révision initiale invalide' using errcode='23514';end if;
 if new.equipment_id is not null and (tg_op='INSERT' or new.equipment_id is distinct from old.equipment_id) and not exists(select 1 from public.equipment_reservations r where r.project_id=new.project_id and r.equipment_id=new.equipment_id and r.state<>'cancelled') then raise exception 'Matériel non sélectionné dans ce projet' using errcode='23514';end if;
 if new.photo_document_id is not null and not exists(select 1 from public.project_documents d where d.id=new.photo_document_id and d.project_id=new.project_id and d.mime_type like 'image/%') then raise exception 'Photo du projet inaccessible' using errcode='23514';end if;
 for c in select * from jsonb_array_elements(new.controls) loop
  if jsonb_typeof(c)<>'object' then raise exception 'Commande invalide' using errcode='23514';end if;
  for k in select jsonb_object_keys(c) loop if k not in ('id','label','section','kind','value','min','max','step','unit') then raise exception 'Propriété inconnue' using errcode='23514';end if;end loop;
  if not (c ?& array['id','label','section','kind','value','min','max','step','unit']) or length(trim(c->>'label')) not between 1 and 100 or length(c->>'section')>100 or length(c->>'unit')>20 or c->>'kind' not in ('knob','fader','switch','selector') then raise exception 'Nom ou type de commande invalide' using errcode='23514';end if;
  foreach k in array array['id','label','section','kind','unit'] loop if jsonb_typeof(c->k)<>'string' then raise exception 'Texte de commande invalide' using errcode='23514';end if;end loop;
  foreach k in array array['min','max','step','value'] loop if jsonb_typeof(c->k)<>'number' then raise exception 'Valeur numérique requise' using errcode='23514';end if;end loop;
  cid:=(c->>'id')::uuid;if cid=any(ids) then raise exception 'Commande dupliquée' using errcode='23514';end if;ids:=array_append(ids,cid);
  lo:=(c->>'min')::numeric;hi:=(c->>'max')::numeric;s:=(c->>'step')::numeric;v:=(c->>'value')::numeric;
  if lo< -1000000 or hi>1000000 or hi<=lo or s<0.0001 or s>hi-lo or v<lo or v>hi then raise exception 'Bornes de potard invalides' using errcode='23514';end if;
  if c->>'kind'='switch' and (lo<>0 or hi<>1 or s<>1 or v not in (0,1)) then raise exception 'Interrupteur invalide' using errcode='23514';end if;
  if c->>'kind'='selector' and (hi-lo)/s>99 then raise exception 'Sélecteur limité à 100 positions' using errcode='23514';end if;
 end loop;
 new.updated_at:=now();return new;
end $$;
revoke all on function public.validate_equipment_setting_preset() from public,anon,authenticated;
create trigger validate_equipment_setting_preset before insert or update on public.equipment_setting_presets for each row execute function public.validate_equipment_setting_preset();

