create function public.acknowledge_operation_item(item_id uuid,expected_revision integer) returns void language plpgsql security invoker set search_path='' as $$declare i public.project_companion_items;begin
 select * into i from public.project_companion_items where id=item_id;if not found or i.revision<>expected_revision or i.tool not in ('changes','handovers') or i.status<>'published' then raise exception 'La consigne a changé ou n’est pas publiée';end if;
 insert into public.operation_acknowledgements(item_id,project_id,user_id,item_revision) values(i.id,i.project_id,auth.uid(),i.revision) on conflict on constraint operation_acknowledgements_pkey do update set item_revision=excluded.item_revision,created_at=now();end $$;
