create function public.apply_project_operation_action(item_id uuid,action_kind text,target_project uuid default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare i public.project_companion_items;pid uuid;target uuid;ed date;starts timestamp;ends timestamp;quantity numeric;price numeric;begin
 select * into i from public.project_companion_items where id=item_id;if not found then raise exception 'Fiche inaccessible' using errcode='42501';end if;pid:=coalesce(target_project,i.project_id);
 if not public.can_manage_project_operations(pid) or (i.tool<>'lessons' and (pid<>i.project_id or not public.can_manage_project_operations(i.project_id))) then raise exception 'Accès refusé' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(item_id::text||action_kind||pid::text,0));
 select target_id into target from public.project_operation_actions a where a.item_id=i.id and a.action=action_kind and a.target_project_id=pid;
 if found then return jsonb_build_object('target_id',target,'already_applied',true);end if;
 if action_kind='task' and i.tool in ('issues','decisions','lessons','onsite_requests') then
  insert into public.project_tasks(project_id,label,assignee,priority) values(pid,left(coalesce(nullif(i.details->>'task_label',''),i.label),200),coalesce(i.details->>'responsible',''),case when i.details->>'priority' in ('high','critical') then 'urgent' else 'normal' end) returning id into target;
 elsif action_kind='log' and i.tool='issues' then
  insert into public.project_companion_items(project_id,tool,label,status,details) values(pid,'logbook',i.label,'recorded',jsonb_build_object('occurred_at',to_char(now() at time zone 'Europe/Paris','YYYY-MM-DD"T"HH24:MI'),'kind','incident','location',coalesce(i.details->>'location',''),'facts',coalesce(i.details->>'problem',''),'followup',coalesce(i.details->>'resolution',''),'responsible',coalesce(i.details->>'responsible',''))) returning id into target;
 elsif action_kind='schedule' and i.tool='interventions' then
  select event_date into ed from public.projects where id=pid;starts:=nullif(i.details->>'starts_at','')::timestamp;ends:=nullif(i.details->>'ends_at','')::timestamp;
  if ed is null or starts is null or (ends is not null and (ends<=starts or ends-starts>=interval '24 hours')) then raise exception 'Renseignez la date du projet et des horaires valides, inférieurs à 24 h';end if;
  insert into public.schedule_items(project_id,title,start_time,end_time,day_offset,speaker,song,cue) values(pid,i.label,starts::time,ends::time,starts::date-ed,left(coalesce(i.details->>'participants',''),200),left(coalesce(i.details->>'music',''),300),left(concat_ws(E'\n',nullif(i.details->>'cue',''),nullif(i.details->>'instructions','')),2000)) returning id into target;
 elsif action_kind='cost' and i.tool='urgent_expenses' and public.is_admin() then
  if i.status not in ('approved','reimbursed') then raise exception 'Validez la dépense avant de l’ajouter aux frais';end if;
  insert into public.project_costs(project_id,label,category,amount,notes) values(pid,i.label,coalesce(i.details->>'category','other'),(i.details->>'amount')::numeric,left(concat_ws(E'\n',i.details->>'paid_by',i.details->>'reference',i.details->>'notes'),2000)) returning id into target;
 elsif action_kind='quote' and i.tool='extras' and public.is_admin() then
  if i.status not in ('approved','invoiced') or nullif(trim(i.details->>'approved_by'),'') is null or nullif(i.details->>'approved_at','') is null then raise exception 'Renseignez l’accord du client avant de créer la ligne de devis';end if;
  quantity:=(i.details->>'quantity')::numeric;price:=(i.details->>'unit_price')::numeric;
  insert into public.project_payments(project_id,label,quantity,unit_price,amount,is_addon,addon_unit,addon_description) values(pid,i.label,quantity,price,round(quantity*price,2),true,i.details->>'unit',left(coalesce(i.details->>'scope',''),2000)) returning id into target;
  update public.project_companion_items set status='invoiced',revision=revision+1 where id=i.id;
 elsif action_kind='restock' and i.tool='replenishment' and i.status='received' then
  target:=nullif(i.details->>'supply_id','')::uuid;if target is null then raise exception 'Choisissez le consommable concerné';end if;
  update public.project_operation_items set details=jsonb_set(details,'{available}',to_jsonb(coalesce((details->>'available')::numeric,0)+(i.details->>'quantity')::numeric)),revision=revision+1 where id=target and project_id=pid and tool='supplies';if not found then raise exception 'Consommable inaccessible';end if;
 else raise exception 'Action non autorisée' using errcode='42501';end if;
 insert into public.project_operation_actions(item_id,action,target_project_id,target_id) values(i.id,action_kind,pid,target);
 return jsonb_build_object('target_id',target,'already_applied',false);
end $$;
revoke all on function public.apply_project_operation_action(uuid,text,uuid) from public,anon;grant execute on function public.apply_project_operation_action(uuid,text,uuid) to authenticated;

create function public.shift_project_schedule(pid uuid,changes jsonb) returns integer language plpgsql security invoker set search_path='' as $$declare c jsonb;s public.schedule_items;count_changed integer:=0;begin
 if not public.can_manage_project_operations(pid) then raise exception 'Accès refusé' using errcode='42501';end if;
 if jsonb_typeof(changes)<>'array' or jsonb_array_length(changes)>2000 or exists(select 1 from jsonb_array_elements(changes) x group by x->>'id' having count(*)>1) then raise exception 'Décalage invalide';end if;
 perform 1 from public.schedule_items where project_id=pid for update;
 for c in select * from jsonb_array_elements(changes) loop
  select * into s from public.schedule_items where id=(c->>'id')::uuid and project_id=pid;
  if not found or s.day_offset is distinct from (c->>'original_day')::int or s.start_time is distinct from (c->>'original_start')::time or s.end_time is distinct from (c->>'original_end')::time then raise exception 'Le planning a changé : rechargez l’aperçu';end if;
  if nullif(c->>'start_time','') is null or nullif(c->>'day_offset','') is null or (c->>'day_offset')::int not between -7 and 30 then raise exception 'Jour ou horaire invalide';end if;
  update public.schedule_items set day_offset=(c->>'day_offset')::int,start_time=(c->>'start_time')::time,end_time=nullif(c->>'end_time','')::time where id=s.id;count_changed:=count_changed+1;
 end loop;return count_changed;end $$;
revoke all on function public.shift_project_schedule(uuid,jsonb) from public,anon;grant execute on function public.shift_project_schedule(uuid,jsonb) to authenticated;

create function public.seed_project_operation_checks(pid uuid,kind text) returns integer language plpgsql security invoker set search_path='' as $$declare label text;event_type text;added integer:=0;cnt integer;g record;s record;missing numeric;begin
 if not public.can_manage_project_operations(pid) then raise exception 'Accès refusé' using errcode='42501';end if;
 if kind in ('opening_checks','closing_checks') then
  select p.event_type into event_type from public.projects p where p.id=pid;
  for label in select unnest(case when kind='opening_checks' then array['Essais son et micros','Contrôle éclairage','Accueil et signalétique prêts','Accès et stationnement confirmés','Sanitaires disponibles','Brief de l’équipe réalisé','Repas et adaptations confirmés','Issues et consignes du lieu vérifiées']||case when event_type='mariage' then array['Entrées et interventions des mariés confirmées','Gâteau et temps forts confirmés'] when event_type='entreprise' then array['Supports des intervenants testés','Ordre de prise de parole confirmé'] else array['Programme validé avec l’organisateur'] end else array['Départ des invités et de l’équipe vérifié','Matériel et accessoires récupérés','Objets confiés restitués ou consignés','Clés et badges rendus','Nettoyage et déchets contrôlés','État des lieux de sortie réalisé','Fermeture confirmée avec le responsable du lieu','Suites administratives et objets trouvés consignés'] end) loop
   insert into public.project_companion_items(project_id,tool,label,status,source_key,details) values(pid,kind,label,'pending','check:'||md5(label),jsonb_build_object('category',case when kind='opening_checks' then 'venue' else 'venue' end)) on conflict(project_id,tool,source_key) do nothing;get diagnostics cnt=row_count;added:=added+cnt;
  end loop;
 elsif kind='meal_service' then
  for g in select coalesce(nullif(table_name,''),'Sans table / groupe') table_name,sum(1+companions) qty,string_agg(distinct nullif(dietary,''),E'\n') dietary from public.project_guests where project_id=pid and response='confirmed' group by coalesce(nullif(table_name,''),'Sans table / groupe') loop
   insert into public.project_companion_items(project_id,tool,label,status,source_key,details) values(pid,kind,g.table_name,'pending','guest-group:'||md5(g.table_name),jsonb_build_object('table_name',g.table_name,'expected',g.qty,'prepared',0,'served',0,'dietary',coalesce(g.dietary,''))) on conflict(project_id,tool,source_key) do nothing;get diagnostics cnt=row_count;added:=added+cnt;
  end loop;
 elsif kind='replenishment' then
  for s in select * from public.project_operation_items where project_id=pid and tool='supplies' and status<>'cancelled' loop
   missing:=coalesce((s.details->>'required')::numeric,0)-coalesce((s.details->>'available')::numeric,0)+coalesce((s.details->>'consumed')::numeric,0);
   if missing>0 then insert into public.project_companion_items(project_id,tool,label,status,source_key,details) values(pid,kind,s.label,'needed','supply:'||s.id::text,jsonb_build_object('supply_id',s.id::text,'quantity',missing,'unit',coalesce(s.details->>'unit',''),'responsible','')) on conflict(project_id,tool,source_key) do nothing;get diagnostics cnt=row_count;added:=added+cnt;end if;
  end loop;
 else raise exception 'Checklist inconnue';end if;return added;end $$;
revoke all on function public.seed_project_operation_checks(uuid,text) from public,anon;grant execute on function public.seed_project_operation_checks(uuid,text) to authenticated;

create table public.project_practical_links(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,token uuid not null unique default gen_random_uuid(),is_open boolean not null default true,created_at timestamptz not null default now());
create index project_practical_links_project_idx on public.project_practical_links(project_id);
alter table public.project_practical_links enable row level security;revoke all on public.project_practical_links from public,anon,authenticated;grant select,insert,update,delete on public.project_practical_links to authenticated;
create policy "Admin practical links" on public.project_practical_links for all to authenticated using((select public.is_admin())) with check((select public.is_admin()));
create function production_private.get_practical_project(link_token uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('title',p.title,'event_date',p.event_date,'information',coalesce((select jsonb_agg(jsonb_build_object('label',i.label,'body',coalesce(i.details->>'body',''),'url',coalesce(i.details->>'url','')) order by i.details->>'category',i.label,i.id) from public.project_companion_items i where i.project_id=p.id and i.tool='practical_info' and i.status='published' and i.details->>'audience'='public'),'[]'::jsonb)) from public.project_practical_links l join public.projects p on p.id=l.project_id where l.token=link_token and l.is_open;
$$;
revoke all on function production_private.get_practical_project(uuid) from public;grant execute on function production_private.get_practical_project(uuid) to anon,authenticated;
create function public.get_practical_project(link_token uuid) returns jsonb language sql stable security invoker set search_path='' as $$select production_private.get_practical_project(link_token);$$;
revoke all on function public.get_practical_project(uuid) from public;grant execute on function public.get_practical_project(uuid) to anon,authenticated;

do $$declare r record;d text;begin for r in select * from companion_preservation loop execute format('select md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text)::text,''[]'')) from public.%I x',r.table_name) into d;if d is distinct from r.digest then raise exception 'Existing data changed: %',r.table_name;end if;end loop;end $$;
